<script setup>
import {computed,onUnmounted,ref,watch} from 'vue'
import request from '../api/request.js'
import {useDecisionResearch} from './useDecisionResearch.js'
import ResearchOpinion from './ResearchOpinion.vue'
import ForecastTracking from './ForecastTracking.vue'
import VersionComparison from './VersionComparison.vue'
import FlowAnalysis from './FlowAnalysis.vue'
import IndustryAnalysis from './IndustryAnalysis.vue'
import MethodPolicyAnalysis from './MethodPolicyAnalysis.vue'
import DecisionCitation from './DecisionCitation.vue'
import DecisionEvidencePanel from './DecisionEvidencePanel.vue'
const props=defineProps({id:String,developer:Boolean})
const {state,history,error,submitting,loading,start,action,active,load,refresh,retry}=useDecisionResearch(props.id)
const resultTab=ref('overview')
const entity=ref(new URLSearchParams(window.location.search).get('entity') || '中微公司'),months=ref(3),citation=ref(null),chain=ref(null),outcomes=ref(null),observing=ref(false),trackingError=ref('')
const report=computed(()=>['P2','P3','P4','P4K'].includes(state.value?.data?.report?.stage)?state.value.data.report:null)
const records=computed(()=>history.value.filter(r=>r.forecast_id))
let disposed=false,trackingTicket=0
onUnmounted(()=>{disposed=true;trackingTicket++})
async function tracking(){
  const ticket=++trackingTicket
  if(!state.value?.forecast_id)return
  try{const [c,o]=await Promise.all([request('/quant/decision/runs/'+props.id+'/forecast'),request('/quant/decision/runs/'+props.id+'/outcomes')]);if(!disposed&&ticket===trackingTicket){chain.value=c;outcomes.value=o;trackingError.value=''}}catch(e){if(!disposed&&ticket===trackingTicket){chain.value=null;outcomes.value=null;trackingError.value=e.message}}
}
watch(()=>state.value?.result_ref,()=>{chain.value=null;outcomes.value=null;tracking()})
async function observe(){if(observing.value)return;observing.value=true;try{await request('/quant/decision/runs/'+props.id+'/observe',{method:'POST',timeoutMs:45000});if(!disposed)await tracking()}catch(e){if(!disposed)trackingError.value=e.message}finally{if(!disposed)observing.value=false}}
async function withdraw(reason){if(observing.value)return;observing.value=true;try{await request('/quant/decision/runs/'+props.id+'/withdraw',{method:'POST',body:JSON.stringify({reason})});if(!disposed)await tracking()}catch(e){if(!disposed)trackingError.value=e.message}finally{if(!disposed)observing.value=false}}
const conditions=(name,parent)=>({entity:name,question:'研究'+name+'未来的经营变化、利润和现金回收原因，按公司业务选择适用方法，核查政策与公司业务的连接，结合行业条件传导、同窗价格与分渠道资金，权衡支持与反对依据，明确选择倾向看多或倾向看空，并说明取舍和改变判断的条件',horizon_months:Number(months.value),research_mode:'medium_term',include_flows:true,include_industry:true,include_methods:true,budget_profile:{max_rounds:1,max_evidence_calls:1},...(parent?{parent_run_id:parent}:{})})
const generate=()=>start(conditions(entity.value))
const update=()=>refresh()
watch(()=>state.value?.subject?.name,value=>{if(value)entity.value=value})
watch(()=>state.value?.request?.horizon_months,value=>{if(value)months.value=value})
</script>
<template>
  <div class="page medium-page">
    <section class="panel rep-section"><div class="section-heading"><h1>未来几个月，倾向看多还是看空</h1><span v-if="developer" class="tag tag-warn">开发者视图</span></div><p class="prediction-lead">先给明确倾向，再看支持理由、反证和改变判断的条件。</p><p v-if="id&&!state&&loading" class="notice" aria-live="polite">正在读取已保存的研究…</p><details v-if="!id||state" :open="!report" class="medium-new"><summary>{{ report?'研究另一家公司':'选择公司与期限' }}</summary><form class="medium-form" @submit.prevent="generate"><label>公司名称或代码<input v-model.trim="entity" required maxlength="80" placeholder="例如：中微公司或688012"></label><label>研究期限<select v-model="months"><option :value="1">未来一个月</option><option :value="2">未来两个月</option><option :value="3">未来三个月</option></select></label><button class="btn btn-primary" :disabled="submitting||active(state)">{{ submitting?'正在提交…':active(state)?'正在研究…':'开始研究' }}</button></form></details><p class="condition-note">重新读取公司披露后生成，按业务选择研究重点，并核查行业、资金和相关政策；缺项明确保留。</p><p v-if="error" class="notice error-text" role="alert">{{ error }} <button class="btn" @click="load">重新读取</button></p></section>
    <section v-if="active(state)" class="panel rep-section" aria-live="polite"><h2>{{ state.model_recovery?'正在恢复分析连接':'正在核查资料与理由' }}</h2><p>{{ developer ? state.model_recovery?.message || state.process.at(-1)?.detail || '正在取得公司资料…' : '正在读取财报、行情与相关政策，并核对支持理由和反证…' }}</p><p class="condition-note">有关键疑问时补查原文，复核完成后展示结论。</p><button class="btn" :disabled="submitting" @click="action('cancel')">停止研究</button></section>
    <section v-if="state&&['FAILED','INTERRUPTED','CANCELLED'].includes(state.status)" class="panel rep-section" role="status"><h2>{{ state.status==='CANCELLED'?'研究已停止':state.failure?.code==='MODEL_UNAVAILABLE'?'分析服务暂时繁忙':'研究需要继续核查' }}</h2><p>{{ state.status==='CANCELLED'?'已取得的资料保留。':state.failure?.message || '本次分析尚未完成复核，已取得的资料保留。' }}</p><p v-if="state.status!=='CANCELLED'" class="condition-note">{{ state.failure?.detail || '继续研究将复用已封存资料、另存新记录，重新核查方向与反证。' }}</p><p v-if="developer" class="condition-note">{{ state.error }}</p><button v-if="state.status!=='CANCELLED'" class="btn btn-primary" :disabled="submitting" @click="retry">{{ submitting?'正在继续…':'继续研究' }}</button></section>
    <section v-if="state?.available_materials&&!report" class="panel rep-section"><h2>{{ state.available_materials.name }} · 已取得的资料</h2><p v-for="(fact,index) in state.available_materials.facts" :key="index">{{ fact.text }}</p><ul><li v-for="doc in state.available_materials.disclosures" :key="doc.title">{{ doc.title }}</li></ul><p class="condition-note">以上为已取得的原始资料，尚不是完成复核的投资判断。</p></section>
    <template v-if="report"><p class="condition-note medium-cutoff">资料截止：{{ new Date(report.cutoff_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}) }}。这是中期研究，与明日方向独立。</p><section v-if="!report.conclusion" class="panel rep-section"><p>这是一份旧版研究，尚未签发明确方向。重新分析会生成新版结论，原记录继续保留。</p><button class="btn btn-primary" :disabled="submitting||active(state)" @click="update">重新分析并给出结论</button></section><div class="result-tabs" role="group" aria-label="研究结果内容"><button v-for="tab in [{id:'overview',label:'结论与反证'},{id:'flows',label:'资金图表'},{id:'industry',label:'行业与政策'},{id:'tracking',label:'后续验证'}]" :key="tab.id" class="btn" :class="{'btn-primary':resultTab===tab.id}" :aria-pressed="resultTab===tab.id" :disabled="tab.id==='flows'&&!state.data.flow_report||tab.id==='industry'&&!state.data.industry_report&&report.stage!=='P4K'" @click="resultTab=tab.id">{{ tab.label }}</button></div><ResearchOpinion v-if="resultTab==='overview'" :report="report" :subject="state.subject" @evidence="citation=$event"/><VersionComparison :id="id" :parent-id="state.parent_run_id || null"/><MethodPolicyAnalysis v-if="resultTab==='industry'&&report.stage==='P4K'" :data="state.data" :developer="developer" @evidence="citation=$event"/><IndustryAnalysis v-if="resultTab==='industry'&&state.data.industry_report" :data="state.data" :developer="developer" @evidence="citation=$event"/><FlowAnalysis v-if="resultTab==='flows'&&state.data.flow_report" :data="state.data" :developer="developer" @evidence="citation=$event"/><p v-if="trackingError" role="alert" class="error-text">{{ trackingError }}</p><ForecastTracking v-if="resultTab==='tracking'" :chain="chain" :outcomes="outcomes" :busy="observing" @observe="observe" @withdraw="withdraw"/><section v-if="resultTab==='overview'" class="panel rep-section"><h2>有新披露时，再检查一次</h2><p class="condition-note">更新会重新取数、另存观点；最初判断和当时依据继续保留。</p><button class="btn" :disabled="submitting||active(state)" @click="update">更新这家公司研究</button></section></template>
    <details v-if="records.length" class="panel rep-section research-history"><summary>已保存的中期研究 · {{ records.length }} 份</summary><a v-for="row in [...records].reverse()" :key="row.run_id" class="prediction-history" :href="'#/decision/'+row.run_id"><span>{{ row.subject?.name || row.title }}</span><span>{{ new Date(row.created_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}) }}</span></a></details>
    <section v-if="state?.status==='COMPLETED'&&!report" class="panel rep-section"><h2>此前保存的单股资料</h2><DecisionEvidencePanel :id="id" :developer="developer"/></section>
    <section v-if="developer&&state" class="panel rep-section"><h2>开发记录</h2><a v-if="report" class="btn" :href="'/api/quant/decision/runs/'+id+'/export'" target="_blank" rel="noopener noreferrer">导出原始观点与完整依据</a><details><summary>方法适用性、补证循环和实际模型调用</summary><pre>{{ JSON.stringify({process:state.process,plan:state.plan,rounds:state.rounds,final_reconciliation:state.final_reconciliation,model_calls:state.model_calls,tokens:state.tokens,charged_tokens:state.charged_tokens,evidence_calls:state.evidence_calls,elapsed_seconds:state.elapsed_seconds,stop_reason:state.stop_reason,calls:state.calls,methods:report?.method_context},null,2) }}</pre></details></section>
    <DecisionCitation v-if="citation" :key="citation" :run-id="id" :evidence-id="citation" :developer="developer" @close="citation=null"/>
  </div>
</template>
<style>.medium-form{display:flex;align-items:flex-end;gap:18px;flex-wrap:wrap;margin:24px 0}.medium-form label{display:flex;flex-direction:column;gap:8px;min-width:180px}.medium-form input,.medium-form select{padding:11px 14px;color:var(--text-1);background:var(--bg-base);border:1px solid var(--border);border-radius:6px;font:inherit}.medium-page pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:65vh;overflow:auto}.medium-cutoff{margin:20px 0}.medium-page .panel{margin-bottom:20px}.medium-page .prediction-source{background:none;border:0;border-bottom:1px solid var(--accent);color:inherit;font:inherit;font-size:12px;cursor:pointer;margin:4px 14px 8px 0;padding:6px 0}.medium-page .prediction-history{display:flex;justify-content:space-between;gap:16px;padding:16px 0;border-bottom:1px solid var(--border);line-height:1.8}.medium-page .prediction-history span:last-child{font-size:12px;opacity:.65}.medium-page :is(button,a,summary):focus-visible{outline:2px solid var(--accent);outline-offset:4px}@media(max-width:700px){.medium-form{align-items:stretch}.medium-form label{width:100%}.medium-form .btn{width:100%}.medium-page .prediction-history{flex-direction:column;gap:4px}.medium-page .section-heading{flex-wrap:wrap;gap:12px}}</style>
